//! Checks the Rust implementation against tests/vectors/crypto-v1.json, which
//! was generated by the Python reference in tools/crypto-reference/.

use std::path::PathBuf;

use serde_json::Value;
use warca_core::crypto::container::{
    self, ObjectSpec, ObjectType, Randomness, HEADER_LEN, NONCE_PREFIX_LEN,
};
use warca_core::crypto::{
    derive_kek, derive_recovery_kek, derive_subkey, object_name, object_path, recovery, unwrap_key,
    wrap_aad, wrap_key_with_nonce, KdfParams, Subkey, WrapPurpose, KEY_LEN, WRAP_NONCE_LEN,
};

fn vectors() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/vectors/crypto-v1.json");
    serde_json::from_slice(&std::fs::read(path).expect("read vectors")).expect("parse vectors")
}

fn hx(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("hex string")).expect("valid hex")
}

fn arr<const N: usize>(v: &Value) -> [u8; N] {
    hx(v).try_into().expect("right length")
}

#[test]
fn argon2id_kek() {
    let v = vectors();
    let cases = v["argon2id"].as_array().unwrap();
    assert_eq!(cases.len(), 2);
    for case in cases {
        let params = KdfParams {
            memory_kib: case["memory_kib"].as_u64().unwrap() as u32,
            iterations: case["iterations"].as_u64().unwrap() as u32,
            lanes: case["lanes"].as_u64().unwrap() as u32,
        };
        let kek = derive_kek(
            case["passphrase"].as_str().unwrap(),
            &hx(&case["salt"]),
            params,
        )
        .unwrap();
        assert_eq!(kek.as_slice(), hx(&case["kek"]), "{}", case["note"]);
    }
}

#[test]
fn passphrase_is_nfc_normalised() {
    let salt = [7u8; 16];
    // "é" precomposed vs "e" + combining acute accent.
    let a = derive_kek("caf\u{e9} passphrase", &salt, KdfParams::MINIMUM).unwrap();
    let b = derive_kek("cafe\u{301} passphrase", &salt, KdfParams::MINIMUM).unwrap();
    assert_eq!(a, b);
}

#[test]
fn hkdf_subkeys() {
    let v = vectors();
    let vmk: [u8; KEY_LEN] = arr(&v["common"]["vault_master_key"]);
    let vault_id = hx(&v["common"]["vault_id"]);
    for which in [Subkey::Index, Subkey::Naming, Subkey::Sync] {
        assert_eq!(
            derive_subkey(&vmk, &vault_id, which).as_slice(),
            hx(&v["subkeys"][which.label()]),
            "{}",
            which.label()
        );
    }
}

#[test]
fn wrap_vmk_by_passphrase() {
    let v = vectors();
    let w = &v["wrap_vmk_by_passphrase"];
    let vmk: [u8; KEY_LEN] = arr(&v["common"]["vault_master_key"]);
    let kek: [u8; KEY_LEN] = arr(&w["kek"]);
    let ctx = hx(&w["context"]);
    let nonce: [u8; WRAP_NONCE_LEN] = arr(&w["nonce"]);
    assert_eq!(wrap_aad(WrapPurpose::VmkByPassphrase, &ctx), hx(&w["aad"]));
    let wrapped = wrap_key_with_nonce(&kek, &vmk, WrapPurpose::VmkByPassphrase, &ctx, &nonce);
    assert_eq!(wrapped.as_slice(), hx(&w["wrapped"]));
    let back = unwrap_key(&kek, &wrapped, WrapPurpose::VmkByPassphrase, &ctx).unwrap();
    assert_eq!(*back, vmk);
    // The same blob must not open in another slot or another vault.
    assert!(unwrap_key(&kek, &wrapped, WrapPurpose::VmkByRecovery, &ctx).is_err());
    let mut other_vault = ctx.clone();
    other_vault[0] ^= 1;
    assert!(unwrap_key(&kek, &wrapped, WrapPurpose::VmkByPassphrase, &other_vault).is_err());
}

#[test]
fn recovery_phrase_and_kek() {
    let v = vectors();
    let r = &v["recovery"];
    let vmk: [u8; KEY_LEN] = arr(&v["common"]["vault_master_key"]);
    let vault_id = hx(&v["common"]["vault_id"]);
    let key: [u8; KEY_LEN] = arr(&r["recovery_key"]);
    let words = r["words"].as_str().unwrap();
    assert_eq!(recovery::words_from_key(&key).as_str(), words);
    assert_eq!(*recovery::key_from_words(words).unwrap(), key);
    // Case and spacing do not matter.
    let messy = format!("  {}  ", words.to_uppercase().replace(' ', "   "));
    assert_eq!(*recovery::key_from_words(&messy).unwrap(), key);
    // BIP39 reference vector: all-zero entropy.
    assert_eq!(
        recovery::words_from_key(&[0u8; 32]).as_str(),
        format!("{}art", "abandon ".repeat(23))
    );

    let rkek = derive_recovery_kek(&key, &vault_id);
    assert_eq!(rkek.as_slice(), hx(&r["recovery_kek"]));
    let nonce: [u8; WRAP_NONCE_LEN] = arr(&r["nonce"]);
    let wrapped = wrap_key_with_nonce(&rkek, &vmk, WrapPurpose::VmkByRecovery, &vault_id, &nonce);
    assert_eq!(wrapped.as_slice(), hx(&r["wrapped_vmk"]));
}

#[test]
fn recovery_phrase_rejects_mistakes() {
    let v = vectors();
    let words: Vec<&str> = v["recovery"]["words"]
        .as_str()
        .unwrap()
        .split(' ')
        .collect();
    // Too few words.
    assert!(recovery::key_from_words(&words[..23].join(" ")).is_err());
    // Two words swapped: the checksum catches it.
    let mut swapped = words.clone();
    swapped.swap(0, 1);
    assert!(recovery::key_from_words(&swapped.join(" ")).is_err());
    // A word not in the list.
    let mut typo = words.clone();
    typo[3] = "warca";
    assert!(recovery::key_from_words(&typo.join(" ")).is_err());
}

#[test]
fn collection_key_wrapping() {
    let v = vectors();
    let c = &v["collection_key"];
    let vmk: [u8; KEY_LEN] = arr(&v["common"]["vault_master_key"]);
    let key: [u8; KEY_LEN] = arr(&c["collection_key"]);
    let mut ctx = hx(&v["common"]["vault_id"]);
    ctx.extend(hx(&c["collection_id"]));
    assert_eq!(ctx, hx(&c["context"]));
    let nonce: [u8; WRAP_NONCE_LEN] = arr(&c["nonce"]);
    let wrapped = wrap_key_with_nonce(&vmk, &key, WrapPurpose::CollectionKey, &ctx, &nonce);
    assert_eq!(wrapped.as_slice(), hx(&c["wrapped"]));
}

#[test]
fn object_naming() {
    let v = vectors();
    let n = &v["object_naming"];
    let naming_key: [u8; KEY_LEN] = arr(&n["naming_key"]);
    let object_id: [u8; 16] = arr(&n["object_id"]);
    assert_eq!(
        object_name(&naming_key, &object_id),
        n["name"].as_str().unwrap()
    );
    assert_eq!(
        object_path(&naming_key, &object_id),
        n["path"].as_str().unwrap()
    );
}

#[test]
fn object_containers() {
    let v = vectors();
    let o = &v["objects"];
    let vault_id = hx(&v["common"]["vault_id"]);
    let dek: [u8; KEY_LEN] = arr(&o["dek"]);
    let wrapping: [u8; KEY_LEN] = arr(&o["dek_wrapping_key"]);
    let wrap_nonce: [u8; WRAP_NONCE_LEN] = arr(&o["wrap_nonce"]);
    let nonce_prefix: [u8; NONCE_PREFIX_LEN] = arr(&o["nonce_prefix"]);
    let spec = ObjectSpec {
        object_type: ObjectType::from_u8(o["object_type"].as_u64().unwrap() as u8).unwrap(),
        object_id: arr(&o["object_id"]),
        collection_id: arr(&o["collection_id"]),
        vault_id: &vault_id,
        dek_wrapping_key: &wrapping,
        chunk_log2: o["chunk_log2"].as_u64().unwrap() as u8,
    };
    let rnd = Randomness {
        dek: &dek,
        wrap_nonce: &wrap_nonce,
        nonce_prefix: &nonce_prefix,
    };
    let cases = o["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 4);
    for case in cases {
        let label = case["label"].as_str().unwrap();
        let plaintext = hx(&case["plaintext"]);
        let expected = hx(&case["object"]);
        let mut out = Vec::new();
        container::encrypt_stream_with(&spec, &rnd, plaintext.as_slice(), &mut out).unwrap();
        assert_eq!(out, expected, "encrypt: {label}");
        let back = container::decrypt_bytes(&expected, &wrapping, &vault_id).unwrap();
        assert_eq!(back.as_slice(), plaintext.as_slice(), "decrypt: {label}");
    }
}

#[test]
fn tampered_objects_are_rejected() {
    let v = vectors();
    let vault_id = hx(&v["common"]["vault_id"]);
    let wrapping: [u8; KEY_LEN] = arr(&v["objects"]["dek_wrapping_key"]);
    let cases = v["must_reject"].as_array().unwrap();
    assert_eq!(cases.len(), 6);
    for case in cases {
        let data = hx(&case["object"]);
        assert!(
            container::decrypt_bytes(&data, &wrapping, &vault_id).is_err(),
            "accepted tampered object: {}",
            case["label"]
        );
    }
}

#[test]
fn more_tampering_and_wrong_keys() {
    let v = vectors();
    let vault_id = hx(&v["common"]["vault_id"]);
    let wrapping: [u8; KEY_LEN] = arr(&v["objects"]["dek_wrapping_key"]);
    let good = hx(&v["objects"]["cases"][3]["object"]);
    let reject = |data: &[u8]| container::decrypt_bytes(data, &wrapping, &vault_id).is_err();

    assert!(!reject(&good));
    // Truncated anywhere: inside the header, at the header, mid-chunk, one byte short.
    for cut in [
        10,
        HEADER_LEN,
        HEADER_LEN + 15,
        HEADER_LEN + 40,
        good.len() - 1,
    ] {
        assert!(reject(&good[..cut]), "accepted truncation at {cut}");
    }
    // A chunk duplicated.
    let full = 64 + 16;
    let mut dup = good[..HEADER_LEN + full].to_vec();
    dup.extend_from_slice(&good[HEADER_LEN..]);
    assert!(reject(&dup));
    // Every single-bit flip in the header and the first chunk.
    for i in 0..HEADER_LEN + full {
        let mut bad = good.clone();
        bad[i] ^= 0x80;
        assert!(reject(&bad), "accepted bit flip at byte {i}");
    }
    // Wrong collection key, wrong vault.
    let mut other_key = wrapping;
    other_key[0] ^= 1;
    assert!(container::decrypt_bytes(&good, &other_key, &vault_id).is_err());
    let mut other_vault = vault_id.clone();
    other_vault[15] ^= 1;
    assert!(container::decrypt_bytes(&good, &wrapping, &other_vault).is_err());
}

#[test]
fn random_round_trips_with_default_chunks() {
    let vault_id = [9u8; 16];
    let key = [3u8; KEY_LEN];
    let spec = |chunk_log2| ObjectSpec {
        object_type: ObjectType::Original,
        object_id: [1u8; 16],
        collection_id: [2u8; 16],
        vault_id: &vault_id,
        dek_wrapping_key: &key,
        chunk_log2,
    };
    for (chunk_log2, len) in [
        (6u8, 0usize),
        (6, 63),
        (6, 64),
        (6, 65),
        (6, 128),
        (20, 3 << 20),
        (20, (2 << 20) + 7),
    ] {
        let plaintext: Vec<u8> = (0..len).map(|i| (i * 31 % 251) as u8).collect();
        let mut ct = Vec::new();
        container::encrypt_stream(&spec(chunk_log2), plaintext.as_slice(), &mut ct).unwrap();
        let back = container::decrypt_bytes(&ct, &key, &vault_id).unwrap();
        assert_eq!(back.as_slice(), plaintext.as_slice(), "len {len}");
    }
}
